import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Platform, Pressable, Text, View } from 'react-native';

import {
  NOTES_TOOLBAR_ACTIONS,
  NOTES_TOOLBAR_DESCRIPTIONS,
  NOTES_TOOLBAR_SHORTCUT_LABELS,
} from '../../lib/notesToolbarActions';
import {
  fetchLatestRelease,
  installedAppVersion,
  isNewerVersion,
  openUrl,
  type LatestRelease,
} from '../../lib/updaterAndroid';
import { usePreferences } from '../../preferences/PreferencesContext';
import { SettingsToggle } from './SettingsToggle';
import { settingsStyles as s } from './settingsStyles';

// Carte de mise à jour NATIVE (Android) — vérifie la dernière release
// GitHub publiée, la compare à la version INSTALLÉE (Platform.constants,
// v0.4.55) et propose le lien direct de l'APK ou la page de téléchargement
// (voir lib/updaterAndroid.ts). Volontairement simple : pas de
// téléchargement in-app — le flux navigateur est le plus fiable.
function MobileUpdateCard() {
  const { theme } = usePreferences();
  const [checking, setChecking] = useState(false);
  const [latest, setLatest] = useState<LatestRelease | null>(null);
  const [error, setError] = useState<string | null>(null);
  const installed = installedAppVersion();
  const aJour = latest !== null && installed !== null && !isNewerVersion(latest.version, installed);

  const handleCheck = useCallback(async () => {
    setChecking(true);
    setError(null);
    try {
      setLatest(await fetchLatestRelease());
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setChecking(false);
    }
  }, []);

  return (
    <View style={[s.card, { backgroundColor: theme.surface, borderColor: theme.border }]}>
      <Text style={[s.cardTitle, { color: theme.text }]}>Mises à jour</Text>
      {installed && <Text style={[s.cardValue, { color: theme.textMuted }]}>Version installée : {installed}</Text>}
      <Pressable onPress={() => void handleCheck()} style={[s.button, { backgroundColor: theme.accent }]} disabled={checking}>
        <Text style={s.buttonText}>{checking ? 'Vérification…' : 'Vérifier les mises à jour'}</Text>
      </Pressable>
      {error ? <Text style={{ color: theme.danger }}>⚠️ {error}</Text> : null}
      {latest ? (
        <>
          {aJour ? (
            <Text style={{ color: theme.textMuted }}>✅ À jour (dernière publiée : v{latest.version}).</Text>
          ) : (
            <>
              <Text style={{ color: theme.text }}>⬆️ Nouvelle version disponible : v{latest.version}</Text>
              {(() => {
                const apkUrl = latest.apkUrl;
                return apkUrl ? (
                  <Pressable onPress={() => openUrl(apkUrl)} style={[s.button, { backgroundColor: theme.accent }]}>
                    <Text style={s.buttonText}>Télécharger l’APK directement</Text>
                  </Pressable>
                ) : null;
              })()}
            </>
          )}
          {!aJour || !latest.apkUrl ? (
            <Pressable
              onPress={() => openUrl(latest.url)}
              style={[s.button, { borderColor: theme.border }]}
            >
              <Text style={{ color: theme.text }}>Ouvrir la page de téléchargement</Text>
            </Pressable>
          ) : null}
          <Text style={{ color: theme.textMuted, fontSize: 12 }}>
            {"Télécharge l'APK, puis ouvre-le (depuis les notifications) pour installer la mise à jour."}
          </Text>
        </>
      ) : null}
    </View>
  );
}

// Section "À propos" — version installée + statut du updater, déplacée
// telle quelle depuis l'ancien SettingsScreen plat (qui l'appelait "Mises à
// jour" sans section dédiée). Sur desktop, dépend de window.updater (Electron,
// voir apps/desktop/electron/preload.ts) ; sur natif, voir MobileUpdateCard.
export function AboutSection() {
  const { theme } = usePreferences();
  const updater = typeof window !== 'undefined' ? window.updater : undefined;

  const [version, setVersion] = useState<string | null>(null);
  const [status, setStatus] = useState<UpdaterStatus>({ state: 'idle' });
  const [autoUpdate, setAutoUpdate] = useState(true);

  useEffect(() => {
    if (!updater) return;
    void updater.getVersion().then(setVersion);
    // Récupère l'état déjà connu du process principal avant de s'abonner :
    // la vérification de mise à jour démarre au lancement de l'app, donc
    // les tout premiers événements (checking/downloading...) peuvent être
    // passés avant même que cet écran ne soit monté. Sans ce snapshot,
    // Paramètres afficherait un état par défaut périmé tant qu'aucun
    // nouvel événement n'arrive.
    void updater.getStatus().then(setStatus);
    void updater.getAutoUpdate().then(setAutoUpdate).catch(() => {});
    const unsubscribe = updater.onStatusChange(setStatus);
    return unsubscribe;
  }, [updater]);

  const handleToggleAutoUpdate = useCallback(
    async (next: boolean) => {
      if (!updater) return;
      setAutoUpdate(next);
      try {
        const applied = await updater.setAutoUpdate(next);
        setAutoUpdate(applied);
      } catch {
        setAutoUpdate(!next);
      }
    },
    [updater],
  );

  const handleDownload = useCallback(async () => {
    if (!updater) return;
    await updater.download();
  }, [updater]);

  const handleCheckForUpdates = useCallback(async () => {
    if (!updater) return;
    await updater.check();
  }, [updater]);

  const handleInstall = useCallback(async () => {
    if (!updater) return;
    try {
      await updater.quitAndInstall();
    } catch (error) {
      console.error('[updater] échec de l’installation :', error);
      setStatus({ state: 'error', message: String(error) });
    }
  }, [updater]);

  // Raccourcis clavier (Ctrl sur Windows/Linux, Cmd sur macOS) —
  // génération depuis les REGISTRES réels plutôt qu'une liste codée en dur
  // qui avait déjà dérivé (elle décrivait Ctrl+K "Recherche globale" alors
  // qu'il ouvre la palette de commandes, et ignorait tout le formatage).
  // Sources : NOTES_TOOLBAR_ACTIONS/NOTES_TOOLBAR_SHORTCUT_LABELS pour
  // l'éditeur (lib/notesToolbarActions.ts — la même source que la barre
  // d'outils et Paramètres → Éditeur), implémentations pour les globaux
  // (AppShell.tsx palette, NotesScreen.tsx S/N, MdxEditor.tsx recherche
  // dans la note). Section purement informative (pas de bridge), affichée
  // AVANT le early-return `!updater` ci-dessous puisque ces raccourcis
  // fonctionnent aussi en web, pas seulement desktop.
  const globalShortcutRows: [string, string][] = [
    ['Ctrl/Cmd + K', 'Palette de commandes & recherche globale'],
    ['Ctrl/Cmd + K (dans l’éditeur)', 'Insérer un lien'],
    ['Ctrl/Cmd + N', 'Nouvelle note'],
    ['Ctrl/Cmd + S', 'Enregistrer la note'],
    ['Ctrl/Cmd + F', 'Rechercher dans la note'],
  ];
  const formattingShortcutRows: [string, string][] = NOTES_TOOLBAR_ACTIONS.filter(
    (action) => action.shortcut,
  ).map((action) => [
    NOTES_TOOLBAR_SHORTCUT_LABELS[action.id] ?? '',
    NOTES_TOOLBAR_DESCRIPTIONS[action.id],
  ]);
  const shortcutRow = ([keys, label]: [string, string]) => (
    <Text key={`${keys} — ${label}`} style={[s.cardValue, { color: theme.textMuted }]}>
      {keys} — {label}
    </Text>
  );
  const shortcuts = (
    <View style={[s.card, { backgroundColor: theme.surface, borderColor: theme.border }]}>
      <Text style={[s.cardTitle, { color: theme.text }]}>Raccourcis clavier</Text>
      <Text style={[s.label, { color: theme.text }]}>Généraux</Text>
      {globalShortcutRows.map(shortcutRow)}
      <Text style={[s.label, { color: theme.text }]}>Formatage (dans l’éditeur)</Text>
      {formattingShortcutRows.map(shortcutRow)}
    </View>
  );

  if (!updater) {
    return (
      <>
        {shortcuts}
        {/* NATIF (Android) : vérification des releases GitHub + ouverture
            de la page de téléchargement de l'APK (voir lib/updaterAndroid.ts).
            L'installation in-app d'un APK exige des permissions système
            spécifiques — le flux navigateur est le plus fiable. */}
        {Platform.OS !== 'web' && <MobileUpdateCard />}
        {Platform.OS === 'web' && (
          <Text style={[s.muted, { color: theme.textMuted }]}>
            Les mises à jour sont disponibles sur la version desktop pour l’instant.
          </Text>
        )}
      </>
    );
  }

  return (
    <>
      {shortcuts}
      <View style={[s.card, { backgroundColor: theme.surface, borderColor: theme.border }]}>
        <Text style={[s.cardTitle, { color: theme.text }]}>Mises à jour</Text>
        <Text style={[s.cardValue, { color: theme.textMuted }]}>Version installée : {version ?? '…'}</Text>

        {status.state === 'idle' && (
          <View style={s.statusRow}>
            <ActivityIndicator size="small" color={theme.accent} />
            <Text style={{ color: theme.textMuted }}>Initialisation…</Text>
          </View>
        )}

        {status.state === 'checking' && (
          <View style={s.statusRow}>
            <ActivityIndicator size="small" color={theme.accent} />
            <Text style={{ color: theme.textMuted }}>Vérification…</Text>
          </View>
        )}

        {status.state === 'up-to-date' && (
          <>
            <Text style={{ color: theme.textMuted }}>✅ À jour.</Text>
            <Pressable onPress={() => void handleCheckForUpdates()} style={[s.button, { backgroundColor: theme.accent }]}>
              <Text style={s.buttonText}>Vérifier les mises à jour</Text>
            </Pressable>
          </>
        )}

        {status.state === 'available' && (
          <>
            <Text style={{ color: theme.textMuted }}>⬇️ Version {status.version} disponible.</Text>
            <Pressable onPress={() => void handleDownload()} style={[s.button, { backgroundColor: theme.accent }]}>
              <Text style={s.buttonText}>Télécharger la mise à jour</Text>
            </Pressable>
          </>
        )}

        {status.state === 'downloading' && (
          <View style={s.statusRow}>
            <ActivityIndicator size="small" color={theme.accent} />
            <Text style={{ color: theme.textMuted }}>
              Téléchargement de la v{status.version ?? '?'}… {status.percent}%
            </Text>
          </View>
        )}

        {status.state === 'ready' && (
          <>
            <Text style={{ color: theme.textMuted }}>🎉 Version {status.version} prête à installer.</Text>
            <Pressable onPress={() => void handleInstall()} style={[s.button, { backgroundColor: theme.accent }]}>
              <Text style={s.buttonText}>Redémarrer et installer</Text>
            </Pressable>
          </>
        )}

        <SettingsToggle
          label="Mise à jour automatique"
          value={autoUpdate}
          onChange={(next) => void handleToggleAutoUpdate(next)}
          theme={theme}
        />
        <Text style={{ color: theme.textMuted, fontSize: 12 }}>
          {autoUpdate
            ? 'Téléchargée en arrière-plan puis installée à la fermeture de l’application.'
            : 'Recherche, téléchargement et installation manuels.'}
        </Text>

        {status.state === 'error' && (
          <>
            {/* v0.4.55 : le message est traduit côté main (updater.ts) et un
                bouton de secours ouvre la page des releases dans le
                navigateur — plus jamais de code brut Chromium à l'écran. */}
            <Text style={{ color: theme.danger }}>⚠️ {status.message}</Text>
            <Pressable onPress={() => void handleCheckForUpdates()} style={[s.button, { backgroundColor: theme.accent }]}>
              <Text style={s.buttonText}>Réessayer</Text>
            </Pressable>
            {updater.openReleasesPage && (
              <Pressable
                onPress={() => void updater.openReleasesPage?.()}
                style={[s.button, { borderColor: theme.border }]}
              >
                <Text style={{ color: theme.text }}>Ouvrir la page des téléchargements</Text>
              </Pressable>
            )}
          </>
        )}
      </View>
    </>
  );
}
